ee:message.ee:set-payload:
%dw 2.0
output application/json

var actionFeatures = [
    "flujo",
    "origen_equipo",
    "PERFIL",
    "score",
    "AutorizoUsoMismaFirma"
]

fun colombiaDate() =
    (now() >> "America/Bogota")

fun orderCreationDate() =
    colombiaDate() as String {format: "yyyy/MM/dd HH:mm:ss"}

fun atdpDate() =
    (colombiaDate() as LocalDateTime)
        as String {format: "yyyy-MM-dd'T'HH:mm:ss"}

---
{
    requestHeader: {
        system: {
            correlationId: vars.correlationId default ""
        }
    },
    requestBody: {
        documentType: payload.requestCustomer.documentType,
        identificationNumber: payload.requestCustomer.documentNumber,
        orderType: payload.through.throughType,
        orderSubtype: payload.through.throughSubtype,
        orderStatus: "PENDIENTE",
        orderCreationDate: orderCreationDate(),
        creatorUser: payload.createdBy,
        modifierUser: payload.updatedBy,
        sellerUser: payload.createdBy,
        channel: payload.channel,
        subchannel: payload.subcategory,
        sourceSystem: "MDM-MOV",
        catalogGroupingNumber: payload.requestService.productGroupingNumber as String,
        invoiceDeliveryType: payload.requestBillingAccount.deliveryType,
        planType: payload.requestService.planType,

        orderCharacteristics:
            payload.featureOrder map (item) ->
                (
                    {
                        characteristic: item.feature,
                        value: item.value as String
                    }
                    ++
                    (
                        if (actionFeatures contains item.feature)
                            {
                                action: item.feature
                            }
                        else
                            {}
                    )
                    ++
                    {
                        extractorUpdate: "1"
                    }
                ),

        setType: payload.setType,

        atdp: {
            date: atdpDate()
        }
    }
}

%dw 2.0 output application/json
var payloadRequest = vars.reqIn
fun colombiaDate(format) = (now() >> "America/Bogota") as String {format: format}
--- { pqrType: "VTA", pqrDate: colombiaDate("dd/MM/yyyy HH:mm:ss"), system: payloadRequest.channel, orderNumber: vars.responseOrderIni.body.databaseId, connectionNumber: "", identification: payloadRequest.requestCustomer.documentNumber, identificationType: payloadRequest.requestCustomer.documentType, user: payloadRequest.channel }

