var orderId = vars.responseOrderIni.body.databaseId default ""
--- { channel: "PORTAL MOVILIDAD", iccid: payload.iccid, externalId: orderId, orderId: orderId, serviceId: orderId ++ "-1", operation: "RESERVAR", resourceType: "ICCID", procedure: "VENTA" }

%dw 2.0
output application/json

var orderId = vars.responseOrderIni.body.databaseId default ""

---
{
  query: {
    update: "MDM_ORDEN",
    updates: [
      {
        q: {
          Numero_Orden: orderId
        },
        u: {
          "\$push": {
            Caracteristicas_Orden: {
              "\$each": [
                {
                  Caracteristica: "ICCID",
                  Valor: payload.iccid default "",
                  Accion: "",
                  actualizacion_extractor: "1"
                },
                {
                  Caracteristica: "MSISDN",
                  Valor: payload.msisdn default "",
                  Accion: "",
                  actualizacion_extractor: "1"
                }
              ]
            }
          }
        },
        multi: false
      }
    ]
  }
}

