%dw 2.0
output application/json

var orderId = vars.responseOrderIni.body.databaseId default ""
var reqIn = vars.reqIn default {}
var resources = vars.responseResources default {}

fun colombiaDateTime() =
    (now() >> "America/Bogota") as String {
        format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"
    }

---
{
  query: {
    insert: "MDM_ACTIVACION_ESIM",
    documents: [
      {
        Fecha_Creacion: {
          "\$date": colombiaDateTime()
        },
        Usuario_Creacion: reqIn.createdBy default reqIn.updatedBy default "",
        Fecha_Modificacion: {
          "\$date": colombiaDateTime()
        },
        Usuario_Modificacion: reqIn.updatedBy default "",
        Canal: reqIn.channel default "",
        Estado: "RESERVADO",
        EnvioResponsys: true,
        Fecha_Activacion: null,
        ICCID: resources.iccid default "",
        MSISDN: resources.msisdn default "",
        IMSI: resources.imsi default "",
        Numero_Documento: reqIn.requestCustomer.documentNumber default "",
        Tipo_Documento: reqIn.requestCustomer.documentType default "",
        Numero_Orden: orderId,
        ParametrosResponsys: [
          {
            Parametro: "EMAIL_ADDRESS_",
            Valor: vars.responseGetCustomer.result[0].Correo_Electronico default ""
          },
          {
            Parametro: "MOBILE_NUMBER_",
            Valor: resources.msisdn default ""
          },
          {
            Parametro: "NOMBRE",
            Valor: vars.responseGetCustomer.result[0].Nombres default ""
          },
          {
            Parametro: "ICCID",
            Valor: resources.iccid default ""
          },
          {
            Parametro: "IMG_QR",
            Valor: ""
          },
          {
            Parametro: "CEDULA",
            Valor: reqIn.requestCustomer.documentNumber default "",
          },
          {
            Parametro: "URL_MANUAL_EQUIPO",
            Valor: ""
          },
          {
            Parametro: "PORTABILIDAD",
            Valor: reqIn.portability default "NO"
          }
        ],
        Reenvio: [],
        Tramite: reqIn.processType default ""
      }
    ]
  }
}

