%dw 2.0
output application/json

var orderId = vars.responseOrderIni.body.databaseId default ""

fun colombiaDateTime() =
    (now() >> "America/Bogota") as String {
        format: "yyyy-MM-dd'T'HH:mm:ss'Z'"
    }

---
{
  query: {
    update: "MDM_ACTIVACION_ESIM",
    updates: [
      {
        q: {
          Numero_Orden: orderId
        },
        u: {
          "\$set": {
            Estado: "ACTIVADO",
            Usuario_Modificacion: vars.reqIn.updatedBy,
            Fecha_Modificacion: {
              "\$date": colombiaDateTime()
            }
          }
        },
        multi: false
      }
    ]
  }
}

